using Microsoft.ML.Data;

namespace TicketClassifier.Models;

public sealed class TicketInput
{
    [LoadColumn(0)]
    public string Subject { get; set; } = string.Empty;

    [LoadColumn(1)]
    public string Description { get; set; } = string.Empty;

    [LoadColumn(2)]
    public float Priority { get; set; }

    [LoadColumn(3)]
    public string Category { get; set; } = string.Empty;
}

public sealed class TicketPrediction
{
    [ColumnName("PredictedLabel")]
    public string Category { get; set; } = string.Empty;

    public float[] Score { get; set; } = [];
}

public sealed class TicketRequest
{
    public string Subject { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Priority { get; set; }
}

public sealed class PredictionResponse
{
    public string PredictedCategory { get; set; } = string.Empty;
    public Dictionary<string, float> Confidence { get; set; } = new();
}

public sealed class MetricsResponse
{
    public double MicroAccuracy { get; set; }
    public double MacroAccuracy { get; set; }
    public double LogLoss { get; set; }
    public double LogLossReduction { get; set; }
}

using Microsoft.ML;
using Microsoft.ML.Data;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public sealed class TicketModelService
{
    private readonly MLContext _mlContext = new(seed: 0);
    private ITransformer _model = null!;
    private PredictionEngine<TicketInput, TicketPrediction> _predictionEngine = null!;
    private MulticlassClassificationMetrics _metrics = null!;
    private VBuffer<ReadOnlyMemory<char>> _labelBuffer;

    public string DataPath { get; set; } =
        Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "Data", "tickets.csv");

    public MulticlassClassificationMetrics TrainAndEvaluate()
    {
        var data = _mlContext.Data.LoadFromTextFile<TicketInput>(
            DataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var pipeline = _mlContext.Transforms.Conversion
                .MapValueToKey("Label", nameof(TicketInput.Category))
            .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketInput.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketInput.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketInput.Priority)))
            .Append(_mlContext.Transforms.NormalizeMinMax("Features"))
            .AppendCacheCheckpoint(_mlContext)
            .Append(_mlContext.MulticlassClassification.Trainers
                .SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        _model = pipeline.Fit(data);

        // Evaluate against training data (small dataset)
        var predictions = _model.Transform(data);
        _metrics = _mlContext.MulticlassClassification.Evaluate(predictions, "Label");

        // Cache label names for confidence mapping
        var labelCol = predictions.Schema["Score"];
        var slotNames = new VBuffer<ReadOnlyMemory<char>>();
        labelCol.GetSlotNames(ref slotNames);
        _labelBuffer = slotNames;

        _predictionEngine = _mlContext.Model.CreatePredictionEngine<TicketInput, TicketPrediction>(_model);

        return _metrics;
    }

    public PredictionResponse Predict(TicketRequest request)
    {
        var input = new TicketInput
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionEngine.Predict(input);

        var labels = _labelBuffer.DenseValues().Select(v => v.ToString()).ToArray();
        var confidence = new Dictionary<string, float>();
        for (var i = 0; i < labels.Length; i++)
            confidence[labels[i]] = prediction.Score[i];

        return new PredictionResponse
        {
            PredictedCategory = prediction.Category,
            Confidence = confidence
        };
    }

    public MetricsResponse GetMetrics() => new()
    {
        MicroAccuracy = _metrics.MicroAccuracy,
        MacroAccuracy = _metrics.MacroAccuracy,
        LogLoss = _metrics.LogLoss,
        LogLossReduction = _metrics.LogLossReduction
    };
}

using Microsoft.AspNetCore.Mvc;
using TicketClassifier.Models;
using TicketClassifier.Services;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public class TicketController(TicketModelService modelService) : ControllerBase
{
    [HttpPost("classify")]
    public ActionResult<PredictionResponse> Classify([FromBody] TicketRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Subject) || string.IsNullOrWhiteSpace(request.Description))
            return BadRequest("Subject and Description are required.");

        if (request.Priority is < 1 or > 3)
            return BadRequest("Priority must be between 1 and 3.");

        return Ok(modelService.Predict(request));
    }

    [HttpGet("metrics")]
    public ActionResult<MetricsResponse> Metrics() => Ok(modelService.GetMetrics());
}

